class Solution {
public:
    int lengthLongestPath(string input) {
        vector<int> lengths;
        int ans = 0;
        int i = 0;
        int n = (int)input.size();
        while (i < n) {
            int depth = 0;
            while (i < n && input[i] == '\t') {
                depth++;
                i++;
            }
            int start = i;
            bool isFile = false;
            while (i < n && input[i] != '\n') {
                if (input[i] == '.') isFile = true;
                i++;
            }
            int nameLen = i - start;
            if (i < n) i++; // skip '\n'

            if (depth >= (int)lengths.size()) lengths.resize(depth + 1);
            int curLen = nameLen + (depth > 0 ? lengths[depth - 1] + 1 : 0);
            lengths[depth] = curLen;

            if (isFile) ans = max(ans, curLen);
        }
        return ans;
    }
};
